const INDICATORS = [{"id":"atr","file":"atr.svg","category":"volatility","name":{"en":"ATR (Average True Range)","hi":"ATR (एवरेज ट्रू रेंज)"},"what":{"en":"The average size of daily price ranges, including gaps. It measures volatility in rupees, not direction.","hi":"अंतराल (gaps) सहित दैनिक कीमत रेंज का औसत आकार। यह दिशा नहीं, अस्थिरता को रुपयों में मापता है।"},"settings":{"en":"14 periods.","hi":"14 अवधि।"},"when":{"en":"To set stop-loss distances and position sizes that fit how much the stock normally moves. Use it for every trade.","hi":"स्टॉप-लॉस की दूरी और पोज़िशन साइज़ तय करने के लिए, जो शेयर की सामान्य चाल के अनुरूप हों। हर ट्रेड के लिए उपयोगी।"},"how":{"en":"Stop distance = 2 × ATR below the entry (for a long trade). Position size = maximum loss ÷ (2 × ATR). Example: entry ₹250, ATR ₹4, stop ₹242 (2 × ATR = ₹8 below). With ₹1,000 maximum loss, size = 1,000 ÷ 8 = 125 shares. Targets of 2 to 3 × ATR keep the reward in proportion.","hi":"स्टॉप की दूरी = एंट्री से नीचे 2 × ATR (लॉन्ग ट्रेड के लिए)। पोज़िशन साइज़ = अधिकतम नुकसान ÷ (2 × ATR)। उदाहरण: एंट्री ₹250, ATR ₹4, स्टॉप ₹242 (2 × ATR = ₹8 नीचे)। ₹1,000 अधिकतम नुकसान पर साइज़ = 1,000 ÷ 8 = 125 शेयर। 2 से 3 × ATR का टारगेट इनाम को अनुपात में रखता है।"},"mistake":{"en":"Using a fixed stop in rupees on every stock. A volatile stock needs a wider stop, or normal noise will stop you out.","hi":"हर शेयर पर रुपयों में एक तय स्टॉप लगाना। ज़्यादा अस्थिर शेयर को चौड़ा स्टॉप चाहिए, वरना सामान्य उतार-चढ़ाव आपको बाहर कर देगा।"},"pairs":{"en":"Any entry signal above, for the stop and size.","hi":"ऊपर का कोई भी एंट्री संकेत, स्टॉप और साइज़ के लिए।"}},{"id":"volume","file":"volume.svg","category":"volume","name":{"en":"Volume","hi":"वॉल्यूम"},"what":{"en":"The number of shares traded in a period. It shows how much participation supports a price move.","hi":"किसी अवधि में ट्रेड हुए शेयरों की संख्या। यह बताता है कि कीमत की चाल को कितनी भागीदारी का समर्थन है।"},"settings":{"en":"Compare with a 20-period average volume.","hi":"20-अवधि के औसत वॉल्यूम से तुलना करें।"},"when":{"en":"To confirm breakouts, reversals and trend moves. Always check it alongside any price signal.","hi":"ब्रेकआउट, पलटाव और ट्रेंड चालों की पुष्टि के लिए। हर कीमत संकेत के साथ इसे जाँचें।"},"how":{"en":"Breakout: buy only if volume is at least 1.5 times its 20-day average on the breakout candle. A rally on falling volume is weak; expect a pullback. Very high volume at the end of a long fall (a climax) can mark exhaustion, but confirm with the next candles.","hi":"ब्रेकआउट: ख़रीदें केवल तब जब ब्रेकआउट कैंडल पर वॉल्यूम 20-दिन के औसत का कम से कम 1.5 गुना हो। घटते वॉल्यूम पर तेज़ी कमज़ोर है; पुलबैक की उम्मीद करें। लंबी गिरावट के अंत में बहुत ज़्यादा वॉल्यूम (क्लाइमैक्स) थकान का संकेत हो सकता है, पर अगली कैंडल से पुष्टि करें।"},"mistake":{"en":"Ignoring volume on a breakout and buying a move that has no buyers behind it.","hi":"ब्रेकआउट पर वॉल्यूम को अनदेखा करना और ऐसी चाल ख़रीदना जिसके पीछे ख़रीदार न हों।"},"pairs":{"en":"Any breakout or pattern (for confirmation), and OBV (for the trend of volume).","hi":"कोई भी ब्रेकआउट या पैटर्न (पुष्टि के लिए), और OBV (वॉल्यूम के ट्रेंड के लिए)।"}},{"id":"vwap","file":"vwap.svg","category":"volume","name":{"en":"VWAP (Volume Weighted Average Price)","hi":"VWAP (वॉल्यूम वेटेड एवरेज प्राइस)"},"what":{"en":"The average price for the day, weighted by volume. Many institutions use it as a fair-value benchmark. It resets every session.","hi":"दिन की औसत कीमत, वॉल्यूम के हिसाब से भारित। कई संस्थान इसे उचित मूल्य (fair value) के मानदंड के रूप में इस्तेमाल करते हैं। यह हर सत्र में नए सिरे से शुरू होता है।"},"settings":{"en":"Intraday: calculated from the session open.","hi":"इंट्राडे: सत्र के ओपन से गणना।"},"when":{"en":"For intraday trades, to see whether buyers or sellers control the session.","hi":"इंट्राडे ट्रेड के लिए, यह देखने के लिए कि सत्र पर ख़रीदार या विक्रेता नियंत्रण में हैं।"},"how":{"en":"Price above VWAP and holding: look for long entries on pullbacks to VWAP, with a stop just below it. Price below VWAP: avoid longs, or look for short setups on rallies back to VWAP. A stop that is too tight below VWAP gets hit by normal noise, so use ATR to size it.","hi":"कीमत VWAP के ऊपर और टिकी हो: VWAP तक पुलबैक पर लॉन्ग एंट्री खोजें, उसके ठीक नीचे स्टॉप के साथ। कीमत VWAP के नीचे हो: लॉन्ग से बचें, या VWAP तक उछाल पर शॉर्ट सेटअप खोजें। VWAP के नीचे बहुत तंग स्टॉप सामान्य उतार-चढ़ाव से बाहर कर देगा, इसलिए ATR से उसका आकार तय करें।"},"mistake":{"en":"Using VWAP on a swing trade or on a stock that opened with a big gap. Its value comes from one session's trading.","hi":"स्विंग ट्रेड पर या बड़े गैप से खुले शेयर पर VWAP इस्तेमाल करना। इसका मूल्य एक सत्र के ट्रेडिंग से आता है।"},"pairs":{"en":"Volume (is the move supported?) and ATR (for stops).","hi":"वॉल्यूम (चाल का समर्थन?) और ATR (स्टॉप के लिए)।"}}];
const GLOSSARY_TERMS = [{"cat":"trading","term":{"en":"Bid and ask","hi":"बिड और आस्क"},"def":{"en":"Bid is the highest price a buyer offers; ask is the lowest price a seller accepts.","hi":"बिड वह सबसे ऊँची कीमत है जो ख़रीदार देता है; आस्क वह सबसे कम कीमत है जिस पर विक्रेता बेचता है।"}},{"cat":"trading","term":{"en":"Spread","hi":"स्प्रेड"},"def":{"en":"The gap between bid and ask. Narrow spreads usually mean a liquid stock.","hi":"बिड और आस्क के बीच का अंतर। कम स्प्रेड आमतौर पर लिक्विड शेयर को दर्शाता है।"}},{"cat":"trading","term":{"en":"Liquidity","hi":"लिक्विडिटी"},"def":{"en":"How easily an asset can be bought or sold without moving its price much.","hi":"कीमत को ज़्यादा प्रभावित किए बिना किसी एसेट को कितनी आसानी से ख़रीदा या बेचा जा सकता है।"}},{"cat":"trading","term":{"en":"Slippage","hi":"स्लिपेज"},"def":{"en":"The difference between the expected price of a trade and the price it actually fills at.","hi":"ट्रेड की अपेक्षित कीमत और वास्तविक भरी गई कीमत के बीच का अंतर।"}},{"cat":"trading","term":{"en":"Leverage","hi":"लीवरेज"},"def":{"en":"Using borrowed money or margin to take a bigger position. It magnifies both gains and losses.","hi":"बड़ी पोज़िशन लेने के लिए उधार या मार्जिन का उपयोग। यह लाभ और नुकसान दोनों बढ़ाता है।"}},{"cat":"trading","term":{"en":"Margin","hi":"मार्जिन"},"def":{"en":"The money you must deposit with a broker to hold a leveraged position.","hi":"लीवरेज्ड पोज़िशन रखने के लिए ब्रोकर के पास जमा करनी पड़ने वाली राशि।"}},{"cat":"trading","term":{"en":"Intraday","hi":"इंट्राडे"},"def":{"en":"Trades opened and closed within the same trading session. Positions must be squared off before the market closes.","hi":"एक ही ट्रेडिंग सत्र में खुले और बंद होने वाले ट्रेड। बाज़ार बंद होने से पहले पोज़िशन बंद करनी होती है।"}},{"cat":"trading","term":{"en":"Brokerage","hi":"ब्रोकरेज"},"def":{"en":"The fee a broker charges for executing a trade.","hi":"ट्रेड पूरा करने के लिए ब्रोकर द्वारा लिया जाने वाला शुल्क।"}},{"cat":"india","term":{"en":"STT (Securities Transaction Tax)","hi":"STT (सिक्योरिटीज़ ट्रांज़ैक्शन टैक्स)"},"def":{"en":"A tax charged by the government on securities transactions, varying by trade type.","hi":"प्रतिभूति लेनदेन पर सरकार द्वारा लगाया जाने वाला टैक्स, जो ट्रेड के प्रकार के अनुसार बदलता है।"}}];
window.MP_PRACTICE = {"intraday-trading":[["replay","Replay the last five days of 5-minute prices and trade only the first hour. Use a stop-loss on every trade.","पिछले पाँच दिनों के 5-मिनट भाव रीप्ले करें और सिर्फ़ पहले घंटे में ट्रेड करें। हर ट्रेड में स्टॉप-लॉस रखें।"],["chart","Add VWAP to a 5-minute chart and note how often price returned to it during the day.","5-मिनट चार्ट पर VWAP जोड़ें और देखें कि दिन में भाव कितनी बार उस पर लौटा।"],["history","Open Trade history and check whether charges ate more than a third of your gross intraday profit.","ट्रेड हिस्ट्री खोलें और देखें कि क्या चार्ज ने आपके कुल इंट्राडे मुनाफ़े का एक-तिहाई से ज़्यादा हिस्सा खा लिया।"]]};
